var ids=['signin','home','conversation','conversation--approval','conversation--menu','conversation--delete','search','activity','activity--work'];doc.pages.filter(p=>/^Proto iOS (Light|Dark)$/.test(p.name)).forEach(function(p){p.layers.filter(l=>l.name.indexOf('Screen/ios/')===0&&ids.indexOf(l.name.split('/').pop())>=0).forEach(function(s){var issues=[];function walk(l){(l.layers||[]).forEach(function(c){if(c.frame.x < -1||c.frame.y < -1||c.frame.x+c.frame.width>l.frame.width+1||c.frame.y+c.frame.height>l.frame.height+1)issues.push({parent:l.name,name:c.name,x:c.frame.x,y:c.frame.y,w:c.frame.width,h:c.frame.height,pw:l.frame.width,ph:l.frame.height});walk(c);});}walk(s);console.log(JSON.stringify({name:s.name,id:String(s.id),issues:issues}));});});